def transform(grid):
    g=[row[:] for row in grid]
    marks=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==5]
    if len(marks)!=2: return g
    # The populated marker anchors the existing motif; copy all its non-marker pixels
    # by the marker-to-marker displacement, and remove the destination marker.
    def score(p):
        r,c=p
        return sum(1/(1+abs(rr-r)+abs(cc-c))
                   for rr,row in enumerate(grid) for cc,v in enumerate(row) if v not in (0,5))
    src=max(marks,key=score)
    dst=marks[0] if marks[1]==src else marks[1]
    dr,dc=dst[0]-src[0],dst[1]-src[1]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v and v!=5:
                rr,cc=r+dr,c+dc
                if 0<=rr<len(g) and 0<=cc<len(g[0]): g[rr][cc]=v
    g[dst[0]][dst[1]]=0
    return g
PY
